 static string Hash(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes));static string HashFile(string path){using var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);return Convert.ToHexString(SHA256.HashData(f));}static bool Eq(string a,string b)=>a!=null&&b!=null&&String.Equals(a,b,StringComparison.OrdinalIgnoreCase);
