 static (double mm,double rad) PoseError(double[] a,double[] b){double distance=1000*Math.Sqrt(new[]{12,13,14}.Sum(i=>(a[i]-b[i])*(a[i]-b[i])));double trace=Enumerable.Range(0,3).Sum(c=>Enumerable.Range(0,3).Sum(i=>a[c*4+i]*b[c*4+i]));return(distance,Math.Acos(Math.Clamp((trace-1)/2,-1,1)));}
