 static string PairKey(string a,string b)=>String.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;
 static bool RawPairCoverage(JsonElement row,bool negative,Guid[] owned,Dictionary<string,Guid> equipment,Dictionary<string,Guid> links){string Role(JsonElement p,string side){string name=p.GetProperty(side).GetString();Guid id=Guid.Parse(p.GetProperty(side+"Id").GetString());if(equipment.TryGetValue(name,out Guid expected)){Need(id==expected,"Exact actual equipment pair UID");return "E:"+name;}if(id==owned[1]){Need(name.EndsWith("_Tool",StringComparison.Ordinal),"Owned tool proxy role");return "T";}if(id==owned[2]){Need(name.EndsWith("_Pipe",StringComparison.Ordinal),"Owned pipe proxy role");return "P";}Need(LinkNames.Contains(name)&&id!=Guid.Empty&&!owned.Contains(id)&&!equipment.Values.Contains(id),"Pair endpoint is an owned copy link");if(!links.TryGetValue(name,out Guid linkId))links.Add(name,id);else Need(linkId==id,"Stable copy link pair UID across every raw sample");Need(links.Values.Distinct().Count()==links.Count,"Distinct seven copy link UIDs");return "L:"+name;}
  var expectedPairs=new HashSet<string>();foreach(string eq in equipment.Keys){foreach(string link in LinkNames)if(!(eq=="Floor"&&link=="Base"))expectedPairs.Add(PairKey("L:"+link,"E:"+eq));expectedPairs.Add(PairKey("T","E:"+eq));expectedPairs.Add(PairKey("P","E:"+eq));}foreach(string link in LinkNames)expectedPairs.Add(PairKey("L:"+link,"P"));expectedPairs.Add(PairKey("T","P"));foreach(string link in LinkNames.Where(v=>v!="Link6"))expectedPairs.Add(PairKey("T","L:"+link));Need(equipment.Count==28&&expectedPairs.Count==265,"Complete fixed 265-pair coverage definition");var actual=new HashSet<string>();bool guide=false;foreach(var pair in row.GetProperty("pairs").EnumerateArray()){string a=Role(pair,"first"),b=Role(pair,"second"),key=PairKey(a,b);Need(actual.Add(key),"No duplicate raw pair");if(negative&&key==PairKey("P","E:InterimFixtureRadialGuides")&&pair.GetProperty("type").GetString()=="Collision"&&!pair.GetProperty("allowed").GetBoolean())guide=true;}Need(actual.SetEquals(expectedPairs),"Every raw sample must contain all 265 exact native pairs");return guide;
 }
